def comps(mask, value_pred, r0=0,r1=20,c0=0,c1=20):
    seen=set(); out=[]
    for r in range(r0,r1):
      for c in range(c0,c1):
        if (r,c) in seen or not value_pred(G[r][c]): continue
        q=[(r,c)]; seen.add((r,c)); cells=[]
        while q:
          p=q.pop(); cells.append(p)
          for d in [(1,0),(-1,0),(0,1),(0,-1)]:
            x,y=p[0]+d[0],p[1]+d[1]
            if r0<=x<r1 and c0<=y<c1 and (x,y) not in seen and value_pred(G[x][y]):
              seen.add((x,y)); q.append((x,y))
        out.append(cells)
    return out
